import numpy as np
from rdkit import Chem
p=np.loadtxt('refined.xyz',skiprows=2,usecols=(1,2,3)); m=Chem.MolFromMolFile('answer.mol',removeHs=False)
for a,b in [(8,74),(25,74),(75,74),(76,74),(75,76)]:print(a,b,np.linalg.norm(p[a]-p[b]))
