# nearest unbonded contacts
bonds={tuple(sorted((b.GetBeginAtomIdx(),b.GetEndAtomIdx()))) for b in m.GetBonds()}
cs=[]
for i in range(len(p)):
 for j in range(i):
  if (j,i) not in bonds and i!=74 and j!=74:
   cs.append((np.linalg.norm(p[i]-p[j]),j,i))
print('nearest nonbonded',sorted(cs)[:12])
